1	// Retention selection for nightly snapshots. See docs/retention.md.
2	
3	export interface Backup {
4	  id: string;
5	  takenAt: string; // ISO date, YYYY-MM-DD
6	  tags: string[];
7	}
8	
9	export interface Policy {
10	  keepDaily: number;
11	  keepWeekly: number;
12	}
13	
14	export function isoWeek(date: string): string {
15	  const d = new Date(`${date}T00:00:00Z`);
16	  const weekday = (d.getUTCDay() + 6) % 7; // Monday = 0
17	  d.setUTCDate(d.getUTCDate() - weekday + 3); // Thursday of this week decides the year
18	  const year = d.getUTCFullYear();
19	  const jan4 = new Date(Date.UTC(year, 0, 4));
20	  const week = 1 + Math.round(((d.getTime() - jan4.getTime()) / 86_400_000 - 3 + ((jan4.getUTCDay() + 6) % 7)) / 7);
21	  return `${year}-W${String(week).padStart(2, "0")}`;
22	}
23	
24	// Newest snapshot per bucket, buckets ordered newest first.
25	function newestPerBucket(sorted: Backup[], key: (b: Backup) => string): Backup[] {
26	  const seen = new Set<string>();
27	  const out: Backup[] = [];
28	  for (const b of sorted) {
29	    const k = key(b);
30	    if (seen.has(k)) continue;
31	    seen.add(k);
32	    out.push(b);
33	  }
34	  return out;
35	}
36	
37	export function selectForDeletion(backups: Backup[], policy: Policy): string[] {
38	  const sorted = [...backups].sort((a, b) => (a.takenAt < b.takenAt ? 1 : a.takenAt > b.takenAt ? -1 : a.id.localeCompare(b.id)));
39	  const keep = new Set<string>();
40	  for (const b of newestPerBucket(sorted, (x) => x.takenAt).slice(0, policy.keepDaily)) keep.add(b.id);
41	  // The current week is already covered by the dailies, so weekly retention starts at the previous week.
42	  const weeks = newestPerBucket(sorted, (x) => isoWeek(x.takenAt));
43	  for (const b of weeks.slice(1, policy.keepWeekly)) keep.add(b.id);
44	  return sorted.filter((b) => !keep.has(b.id)).map((b) => b.id);
45	}
46

1	import { test } from "node:test";
2	import assert from "node:assert/strict";
3	import { selectForDeletion, type Backup } from "../src/prune.ts";
4	
5	function nightly(from: string, days: number): Backup[] {
6	  const out: Backup[] = [];
7	  const d = new Date(`${from}T00:00:00Z`);
8	  for (let i = 0; i < days; i++) {
9	    const date = d.toISOString().slice(0, 10);
10	    out.push({ id: `bk-vol1-${date}`, takenAt: date, tags: [] });
11	    d.setUTCDate(d.getUTCDate() + 1);
12	  }
13	  return out;
14	}
15	
16	test("keeps four weekly snapshots when keepWeekly is 4", () => {
17	  // 2026-08-03 is a Monday; 35 nights run to Sunday 2026-09-06. Archive volumes use keepDaily 0.
18	  const backups = nightly("2026-08-03", 35);
19	  const deleted = selectForDeletion(backups, { keepDaily: 0, keepWeekly: 4 });
20	  const kept = backups.map((b) => b.id).filter((id) => !deleted.includes(id));
21	  assert.deepEqual(kept, [
22	    "bk-vol1-2026-08-16",
23	    "bk-vol1-2026-08-23",
24	    "bk-vol1-2026-08-30",
25	    "bk-vol1-2026-09-06",
26	  ]);
27	});
